-- Eleven Australia and Aveda's logos had huge transparent padding around a
-- small mark, which made them look tiny next to the other brand logos on the
-- landing page. This re-crops them tight to the actual artwork.

update brands set logo_url = 'data:image/png;base64,' where name = 'Eleven Australia';

update brands set logo_url = 'data:image/png;base64,' where name = 'Aveda';
